async deleteRegistryAndCheckpoint(input: {
		collectionId: string;
		collectionSlug: string;
		leaseToken: string;
	}): Promise<boolean> {
		return withTransaction(this.db, async (trx) => {
			await trx
				.deleteFrom("_emdash_collections")
				.where("id", "=", input.collectionId)
				.where("slug", "=", input.collectionSlug)
				.where((eb) =>
					eb.exists(
						eb
							.selectFrom("_emdash_media_usage_collection_deletions as deletion")
							.select("deletion.collection_id")
							.where("deletion.collection_id", "=", input.collectionId)
							.where("deletion.collection_slug", "=", input.collectionSlug)
							.where("deletion.state", "=", "leased")
							.where("deletion.phase", "=", "registry")
							.where("deletion.lease_token", "=", input.leaseToken)
							.where(liveLease(trx, "deletion.lease_expires_at")),
					),
				)
				.execute();

			const checkpoint = await trx
				.updateTable("_emdash_media_usage_collection_deletions")
				.set({ phase: "table", updated_at: timestampOffset(trx, 0) })
				.where("collection_id", "=", input.collectionId)
				.where("collection_slug", "=", input.collectionSlug)
				.where("state", "=", "leased")
				.where("phase", "=", "registry")
				.where("lease_token", "=", input.leaseToken)
				.where(liveLease(trx))
				.executeTakeFirst();
			return Number(checkpoint.numUpdatedRows ?? 0) === 1;
		});
	}

async function executeCollectionDeletionGuard(
	db: Kysely<Database>,
	input: CollectionDeletionGuardInput,
): Promise<CollectionDeletionGuardResult> {
	const executeAdapterGuard = await loadAdapterCollectionDeletionGuard();
	if (executeAdapterGuard) {
		const { default: config } = await import("virtual:emdash/config");
		return executeAdapterGuard(config.database?.config, input);
	}
	return executeLocalCollectionDeletionGuard(db, input);
}

export async function executeLocalCollectionDeletionGuard(
	db: Kysely<Database>,
	input: CollectionDeletionGuardInput,
): Promise<CollectionDeletionGuardResult> {
	assertGuardInput(input);
	return db.transaction().execute(async (trx) => {
		if (!(await lockLiveTombstone(trx, input))) return { outcome: "stale" };
		if (input.action === "fence") return fenceCollection(trx, input);

		const fts = new FTSManager(trx);
		await fts.dropFtsTable(input.collectionSlug);
		await sql`DROP TABLE IF EXISTS ${sql.ref(`ec_${input.collectionSlug}`)}`.execute(trx);
		return { outcome: "dropped" };
	});
}

async function fenceCollection(
	trx: Transaction<Database>,
	input: Extract<CollectionDeletionGuardInput, { action: "fence" }>,
): Promise<CollectionDeletionGuardResult> {
	const tableName = `ec_${input.collectionSlug}`;
	validateIdentifier(tableName, "content table");
	if (isPostgres(trx)) {
		await sql`LOCK TABLE ${sql.ref(tableName)} IN SHARE ROW EXCLUSIVE MODE`.execute(trx);
	}

	if (!input.forceDelete) {
		const content = await sql<{ present: number }>`
			SELECT 1 AS present FROM ${sql.ref(tableName)}
			WHERE deleted_at IS NULL
			LIMIT 1
		`.execute(trx);
		if (content.rows.length > 0) return { outcome: "has_content" };
	}

	const result = await trx
		.updateTable("_emdash_media_usage_index_status as status")
		.set({ capture_state: "deleting", updated_at: timestampOffset(trx, 0) })
		.where("status.adapter_id", "=", "content-media")
		.where("status.scope_type", "=", "collection")
		.where("status.scope_key", "=", input.collectionSlug)
		.where("status.collection_id", "=", input.collectionId)
		.where("status.capture_state", "=", "active")
		.where((eb) =>
			eb.exists(
				eb
					.selectFrom("_emdash_collections as collection")
					.select("collection.id")
					.where("collection.id", "=", input.collectionId)
					.where("collection.slug", "=", input.collectionSlug),
			),
		)
		.executeTakeFirst();
	return Number(result.numUpdatedRows ?? 0) === 1 ? { outcome: "fenced" } : { outcome: "stale" };
}

async function lockLiveTombstone(
	trx: Transaction<Database>,
	input: CollectionDeletionGuardInput,
): Promise<boolean> {
	const phase = input.action === "fence" ? "fence" : "table";
	if (isPostgres(trx)) {
		const row = await trx
			.selectFrom("_emdash_media_usage_collection_deletions")
			.select("collection_id")
			.where("collection_id", "=", input.collectionId)
			.where("collection_slug", "=", input.collectionSlug)
			.where("state", "=", "leased")
			.where("phase", "=", phase)
			.where("lease_token", "=", input.leaseToken)
			.where(liveLease(trx))
			.forUpdate()
			.executeTakeFirst();
		return row !== undefined;
	}

	const locked = await trx
		.updateTable("_emdash_media_usage_collection_deletions")
		.set({ updated_at: sql<string>`updated_at` })
		.where("collection_id", "=", input.collectionId)
		.where("collection_slug", "=", input.collectionSlug)
		.where("state", "=", "leased")
		.where("phase", "=", phase)
		.where("lease_token", "=", input.leaseToken)
		.where(liveLease(trx))
		.executeTakeFirst();
	return Number(locked.numUpdatedRows ?? 0) === 1;
}

function liveLease(db: Kysely<Database>, column = "lease_expires_at"): RawBuilder<boolean> {
	const leaseExpiresAt = sql.ref(column);
	return isPostgres(db)
		? sql<boolean>`${leaseExpiresAt}::timestamptz > clock_timestamp()`
		: sql<boolean>`${leaseExpiresAt} > strftime('%Y-%m-%dT%H:%M:%fZ', 'now')`;
}

function timestampOffset(db: Kysely<Database>, offsetSeconds: number): RawBuilder<string> {
	if (isPostgres(db)) {
		return sql<string>`to_char(
			(clock_timestamp() AT TIME ZONE 'UTC') + (${offsetSeconds} * INTERVAL '1 second'),
			'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
		)`;
	}
	return sql<string>`strftime(
		'%Y-%m-%dT%H:%M:%fZ',
		'now',
		${`${offsetSeconds >= 0 ? "+" : ""}${offsetSeconds} seconds`}
	)`;
}

async function processWorkBatch(
	db: Kysely<Database>,
	claim: MediaUsageCollectionDeletionRecord & { leaseToken: string },
): Promise<boolean> {
	await withTransaction(db, async (trx) => {
		const rows = await trx
			.selectFrom("_emdash_media_usage_work")
			.select("content_id")
			.where("collection_id", "=", claim.collectionId)
			.$if(claim.workCursor !== null, (query) => query.where("content_id", ">", claim.workCursor!))
			.orderBy("content_id", "asc")
			.limit(MEDIA_USAGE_COLLECTION_DELETION_LIMITS.rowsPerBatch + 1)
			.execute();
		const batch = rows.slice(0, MEDIA_USAGE_COLLECTION_DELETION_LIMITS.rowsPerBatch);
		if (batch.length > 0) {
			await trx
				.deleteFrom("_emdash_media_usage_work")
				.where("collection_id", "=", claim.collectionId)
				.where(
					"content_id",
					"in",
					batch.map((row) => row.content_id),
				)
				.where(liveLeaseGuard(trx, claim))
				.execute();
		}
		await updateDeletion(trx, claim, {
			phase: rows.length > MEDIA_USAGE_COLLECTION_DELETION_LIMITS.rowsPerBatch ? "work" : "sources",
			work_cursor:
				rows.length > MEDIA_USAGE_COLLECTION_DELETION_LIMITS.rowsPerBatch
					? batch.at(-1)!.content_id
					: null,
		});
	});
	return false;
}

async function processSourceBatch(
	db: Kysely<Database>,
	claim: MediaUsageCollectionDeletionRecord & { leaseToken: string },
): Promise<boolean> {
	await withTransaction(db, async (trx) => {
		let sourceKey = claim.sourceKey;
		if (!sourceKey) {
			const source = await trx
				.selectFrom("_emdash_media_usage_sources")
				.select("source_key")
				.where("source_type", "=", "content")
				.where("collection_id", "=", claim.collectionId)
				.orderBy("source_key", "asc")
				.limit(1)
				.executeTakeFirst();
			if (!source) {
				await updateDeletion(trx, claim, {
					phase: "status",
					source_key: null,
					occurrence_cursor: null,
				});
				return;
			}
			sourceKey = source.source_key;
			await updateDeletion(trx, claim, { source_key: sourceKey, occurrence_cursor: null });
		}

		const occurrences = await trx
			.selectFrom("_emdash_media_usage")
			.select("id")
			.where("source_key", "=", sourceKey)
			.$if(claim.occurrenceCursor !== null, (query) =>
				query.where("id", ">", claim.occurrenceCursor!),
			)
			.orderBy("id", "asc")
			.limit(MEDIA_USAGE_COLLECTION_DELETION_LIMITS.rowsPerBatch + 1)
			.execute();
		const batch = occurrences.slice(0, MEDIA_USAGE_COLLECTION_DELETION_LIMITS.rowsPerBatch);
		if (batch.length > 0) {
			await trx
				.deleteFrom("_emdash_media_usage")
				.where("source_key", "=", sourceKey)
				.where(
					"id",
					"in",
					batch.map((row) => row.id),
				)
				.where(liveLeaseGuard(trx, claim))
				.execute();
		}
		if (occurrences.length > MEDIA_USAGE_COLLECTION_DELETION_LIMITS.rowsPerBatch) {
			await updateDeletion(trx, claim, {
				source_key: sourceKey,
				occurrence_cursor: batch.at(-1)!.id,
			});
			return;
		}
		await trx
			.deleteFrom("_emdash_media_usage_sources")
			.where("source_key", "=", sourceKey)
			.where("source_type", "=", "content")
			.where("collection_id", "=", claim.collectionId)
			.where(liveLeaseGuard(trx, claim))
			.execute();
		await updateDeletion(trx, claim, { source_key: null, occurrence_cursor: null });
	});
	return false;
}

async function processStatus(
	db: Kysely<Database>,
	claim: MediaUsageCollectionDeletionRecord & { leaseToken: string },
): Promise<boolean> {
	await withTransaction(db, async (trx) => {
		if (await exactCleanupRowsRemain(trx, claim, false)) {
			throw new Error("Collection deletion cleanup is incomplete");
		}
		await trx
			.deleteFrom("_emdash_media_usage_reconciliations")
			.where("collection_id", "=", claim.collectionId)
			.where("collection_slug", "=", claim.collectionSlug)
			.where(liveLeaseGuard(trx, claim))
			.execute();
		await trx
			.deleteFrom("_emdash_media_usage_index_status")
			.where("adapter_id", "=", "content-media")
			.where("scope_type", "=", "collection")
			.where("scope_key", "=", claim.collectionSlug)
			.where("collection_id", "=", claim.collectionId)
			.where(liveLeaseGuard(trx, claim))
			.execute();
		await updateDeletion(trx, claim, { phase: "finalize" });
	});
	return false;
}

async function finalizeDeletion(
	db: Kysely<Database>,
	claim: MediaUsageCollectionDeletionRecord & { leaseToken: string },
): Promise<boolean> {
	if (await tableExists(db, `ec_${claim.collectionSlug}`)) {
		throw new Error("Collection table still exists during deletion finalization");
	}
	if (await exactCleanupRowsRemain(db, claim)) throw new Error("Collection deletion is incomplete");
	const registry = await db
		.selectFrom("_emdash_collections")
		.select("id")
		.where("id", "=", claim.collectionId)
		.where("slug", "=", claim.collectionSlug)
		.executeTakeFirst();
	if (registry) throw new Error("Collection registry identity still exists");
	const result = await db
		.deleteFrom("_emdash_media_usage_collection_deletions")
		.where("collection_id", "=", claim.collectionId)
		.where("collection_slug", "=", claim.collectionSlug)
		.where("state", "=", "leased")
		.where("phase", "=", "finalize")
		.where("lease_token", "=", claim.leaseToken)
		.where(liveLeaseGuard(db, claim))
		.executeTakeFirst();
	if (Number(result.numDeletedRows ?? 0) !== 1)
		throw new Error("Collection deletion lost finalization");
	return true;
}

async function exactCleanupRowsRemain(
	db: DatabaseExecutor,
	claim: Pick<MediaUsageCollectionDeletionRecord, "collectionId" | "collectionSlug">,
	includeStatus = true,
): Promise<boolean> {
	const result = await sql<{
		work_present: boolean | number;
		source_present: boolean | number;
		status_present: boolean | number;
	}>`
		SELECT
			EXISTS (
				SELECT 1 FROM _emdash_media_usage_work
				WHERE collection_id = ${claim.collectionId}
			) AS work_present,
			EXISTS (
				SELECT 1 FROM _emdash_media_usage_sources
				WHERE source_type = 'content' AND collection_id = ${claim.collectionId}
			) AS source_present,
			EXISTS (
				SELECT 1 FROM _emdash_media_usage_index_status
				WHERE adapter_id = 'content-media'
					AND scope_type = 'collection'
					AND scope_key = ${claim.collectionSlug}
					AND collection_id = ${claim.collectionId}
			) AS status_present
	`.execute(db);
	const row = result.rows[0];
	return (
		Boolean(row?.work_present) ||
		Boolean(row?.source_present) ||
		(includeStatus && Boolean(row?.status_present))
	);
}

async function updateDeletion(
	db: DatabaseExecutor,
	claim: MediaUsageCollectionDeletionRecord & { leaseToken: string },
	values: Updateable<MediaUsageCollectionDeletionTable>,
): Promise<void> {
	const result = await db
		.updateTable("_emdash_media_usage_collection_deletions")
		.set({
			...values,
			attempt_count: 0,
			last_error_code: null,
			updated_at: collectionDeletionCurrentTimestamp(db),
		})
		.where("collection_id", "=", claim.collectionId)
		.where("state", "=", "leased")
		.where("lease_token", "=", claim.leaseToken)
		.where(liveLeaseGuard(db, claim))
		.executeTakeFirst();
	if (Number(result.numUpdatedRows ?? 0) !== 1)
		throw new Error("Collection deletion lease was lost");
}

function liveLeaseGuard(
	db: DatabaseExecutor,
	claim: Pick<MediaUsageCollectionDeletionRecord, "collectionId"> & { leaseToken: string },
): RawBuilder<boolean> {
	return isPostgres(db)
		? sql<boolean>`EXISTS (
			SELECT 1 FROM _emdash_media_usage_collection_deletions AS deletion
			WHERE deletion.collection_id = ${claim.collectionId}
				AND deletion.state = 'leased'
				AND deletion.lease_token = ${claim.leaseToken}
				AND deletion.lease_expires_at::timestamptz > clock_timestamp()
		)`
		: sql<boolean>`EXISTS (
			SELECT 1 FROM _emdash_media_usage_collection_deletions AS deletion
			WHERE deletion.collection_id = ${claim.collectionId}
				AND deletion.state = 'leased'
				AND deletion.lease_token = ${claim.leaseToken}
				AND deletion.lease_expires_at > strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
		)`;
}
